","import React, { useState, useEffect } from "react";
import {
 NowRecordListConnected,
} from "@servicenow/react-components/NowRecordListConnected";

interface Props {
 onViewIncidents: () => void;
 onSelectIncident: (id: string) => void;
}

interface Metrics {
 totalOpen: number;
 criticalHigh: number;
 resolved: number;
 p1Active: number;
}

export default function Dashboard({ onViewIncidents, onSelectIncident }: Props) {
 const [metrics, setMetrics] = useState<Metrics | null>(null);

 useEffect(() => {
 const token = (window as any).g_ck || "";
 const hdrs = { "X-UserToken": token, Accept: "application/json" };

 function fetchCount(q: string): Promise<number> {
 return fetch(
 "/api/now/stats/incident?sysparm_query=" + encodeURIComponent(q) + "&sysparm_count=true",
 { headers: hdrs }
 )
 .then(function (r) { return r.json(); })
 .then(function (d) { return parseInt(d.result.stats.count, 10) || 0; })
 .catch(function () { return 0; });
 }

 Promise.all([
 fetchCount("active=true"),
 fetchCount("active=true^priorityIN1,2"),
 fetchCount("state=6"),
 fetchCount("active=true^priority=1"),
 ]).then(function (results) {
 setMetrics({
 totalOpen: results[0],
 criticalHigh: results[1],
 resolved: results[2],
 p1Active: results[3],
 });
 });
 }, []);

 return (
 <div className="campus-app">
 <div className="campus-header">
 <h1 className="section-title">CampusDesk AI Dashboard</h1>
 <span className="nav-link" onClick={onViewIncidents}>
 {"View All Incidents \u2192"}
 </span>
 </div>

 <div className="metrics-grid">
 <div className="metric-card" style={{ borderTopColor: "#0080a3" }}>
 <div className="metric-value">{metrics ? metrics.totalOpen : "..."}</div>
 <div className="metric-label">Total Open</div>
 </div>
 <div className="metric-card" style={{ borderTopColor: "#c4314b" }}>
 <div className="metric-value">{metrics ? metrics.criticalHigh : "..."}</div>
 <div className="metric-label">Critical / High</div>
 </div>
 <div className="metric-card" style={{ borderTopColor: "#2e8540" }}>
 <div className="metric-value">{metrics ? metrics.resolved : "..."}</div>
 <div className="metric-label">Resolved</div>
 </div>
 <div className="metric-card" style={{ borderTopColor: "#e07c00" }}>
 <div className="metric-value">{metrics ? metrics.p1Active : "..."}</div>
 <div className="metric-label">P1 Active</div>
 </div>
 </div>

 <h2 className="section-title" style={{ marginBottom: "0.5rem" }}>Recent Open Incidents</h2>
 <NowRecordListConnected
 key="active=true"
 table="incident"
 listTitle="Open Incidents"
 columns="number,short_description,priority,state,assigned_to"
 hideHeader={true}
 limit={10}
 onRowClicked={function (e: any) {
 onSelectIncident(e.detail.payload.sys_id);
 }}
 />
 </div>
 );
}
