","import React from "react";
import { RecordProvider } from "@servicenow/react-components/RecordContext";
import { FormActionBar } from "@servicenow/react-components/FormActionBar";
import { FormColumnLayout } from "@servicenow/react-components/FormColumnLayout";

interface Props {
 incidentId: string;
 onBack: () => void;
}

export default function IncidentDetail({ incidentId, onBack }: Props) {
 return (
 <div className="campus-app">
 <div className="campus-header">
 <h1 className="section-title">Incident Detail</h1>
 <span className="nav-link" onClick={onBack}>
 {"\u2190 Back to Incidents"}
 </span>
 </div>
 <RecordProvider table="incident" sysId={incidentId} isReadOnly={false}>
 <FormActionBar />
 <FormColumnLayout />
 </RecordProvider>
 </div>
 );
}
","import React, { useState, useEffect, useCallback } from "react";
import Dashboard from "./components/Dashboard";
import IncidentList from "./components/IncidentList";
import IncidentDetail from "./components/IncidentDetail";
import "./styles.css";

interface ViewState {
 view: string;
 recordId: string | null;
}

function getViewFromUrl(): ViewState {
 const params = new URLSearchParams(window.location.search);
 return {
 view: params.get("view") || "dashboard",
 recordId: params.get("id") || null,
 };
}

export default function App() {
 const [currentView, setCurrentView] = useState<ViewState>(getViewFromUrl);

 useEffect(() => {
 const onPop = () => setCurrentView(getViewFromUrl());
 window.addEventListener("popstate", onPop);
 return () => window.removeEventListener("popstate", onPop);
 }, []);

 const navigateTo = useCallback(
 (view: string, id?: string | null, title?: string) => {
 const params = new URLSearchParams({ view });
 if (id) params.set("id", id);
 const path = window.location.pathname + "?" + params.toString();
 const pageTitle = title || "CampusDesk AI - " + view;

 if (window.self !== window.top) {
 try {
 (window as any).CustomEvent.fireTop(
 "magellanNavigator.permalink.set",
 { relativePath: path, title: pageTitle }
 );
 } catch (_e) { /* ignore */ }
 }
 window.history.pushState({ view, id }, "", path);
 document.title = pageTitle;
 setCurrentView({ view, recordId: id || null });
 },
 []
 );

 const { view, recordId } = currentView;

 if (view === "detail" && recordId) {
 return (
 <IncidentDetail
 incidentId={recordId}
 onBack={() => navigateTo("incidents")}
 />
 );
 }

 if (view === "incidents") {
 return (
 <IncidentList
 onSelect={(id: string) => navigateTo("detail", id)}
 onBack={() => navigateTo("dashboard")}
 />
 );
 }

 return (
 <Dashboard
 onViewIncidents={() => navigateTo("incidents")}
 onSelectIncident={(id: string) => navigateTo("detail", id)}
 />
 );
}
","import React from "react";
import ReactDOM from "react-dom/client";
import App from "./app";

function mount() {
 const el = document.getElementById("root");
 if (!el) return;
 ReactDOM.createRoot(el).render(<App />);
}

if (document.readyState === "complete") {
 mount();
} else {
 window.addEventListener("load", mount);
}
",".campus-app {
 padding: 1rem 1.5rem;
 font-family: "Lato", "Source Sans Pro", Arial, sans-serif;
 background: #f4f5f7;
 min-height: 100vh;
 color: #10171a;
}

.campus-header {
 display: flex;
 align-items: center;
 justify-content: space-between;
 margin-bottom: 1.5rem;
 padding-bottom: 0.75rem;
 border-bottom: 1px solid #cfd5d7;
}

.section-title {
 font-size: 1.25rem;
 font-weight: 600;
 color: #10171a;
 margin: 0;
}

.nav-link {
 color: #0080a3;
 cursor: pointer;
 font-weight: 500;
 font-size: 0.875rem;
}

.nav-link:hover {
 text-decoration: underline;
 color: #005a73;
}

.metrics-grid {
 display: grid;
 grid-template-columns: repeat(4, 1fr);
 gap: 1rem;
 margin-bottom: 1.5rem;
}

.metric-card {
 background: #ffffff;
 border-radius: 8px;
 border-top: 4px solid #0080a3;
 box-shadow: 0 1px 4px rgba(0, 0, 0, 0.1);
 padding: 1.25rem 1rem;
 text-align: center;
}

.metric-value {
 font-size: 2rem;
 font-weight: 700;
 color: #10171a;
 line-height: 1.2;
}

.metric-label {
 font-size: 0.75rem;
 color: #4b5559;
 margin-top: 0.5rem;
 text-transform: uppercase;
 letter-spacing: 0.05em;
}

.detail-back {
 margin-bottom: 1rem;
}
","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
